"use client";
import{useCallback,useEffect,useState}from"react";import{AppShell}from"../ui/app-shell";import{deleteQueuedItem,readQueue,retryQueuedItem,syncQueue,SYNC_EVENT,type QueueRecord}from"../../lib/offline-sync";import"../sync.css";
const when=(value:string)=>new Date(value).toLocaleString();
export default function SyncPage(){const[items,setItems]=useState<QueueRecord[]>([]);const[online,setOnline]=useState(true);const[working,setWorking]=useState(false);const[message,setMessage]=useState("");const load=useCallback(async()=>{setOnline(navigator.onLine);setItems(await readQueue())},[]);useEffect(()=>{const timer=setTimeout(()=>void load(),0);const change=()=>void load();window.addEventListener(SYNC_EVENT,change);window.addEventListener("online",change);window.addEventListener("offline",change);return()=>{clearTimeout(timer);window.removeEventListener(SYNC_EVENT,change);window.removeEventListener("online",change);window.removeEventListener("offline",change)}},[load]);const sync=async()=>{setWorking(true);const result=await syncQueue(true);setWorking(false);setMessage(result.synced?`${result.synced} item${result.synced===1?"":"s"} securely synced.`:result.reason==="offline"?"Still offline. Your queued work remains on this device.":"Nothing was ready to sync.");await load()};const retry=async(id:string)=>{setWorking(true);await retryQueuedItem(id);setWorking(false);await load()};const discard=async(id:string)=>{if(!window.confirm("Discard this queued item from this device? This cannot be undone."))return;await deleteQueuedItem(id);await load()};return <AppShell active="sync"><header className="page-heading"><div><p className="eyebrow">Package 7H.1 · Reliable synchronisation</p><h1>Your work has a receipt.</h1><p>See what is stored on this device, what is waiting for a connection and what needs your attention.</p></div><button className="primary-action" disabled={!online||working||!items.length} onClick={sync}>{working?"Syncing…":"Sync now"}</button></header>{message&&<div className="success-banner">{message}</div>}<section className={`connection-card ${online?"online":"offline"}`}><span>{online?"●":"○"}</span><div><strong>{online?"Connected":"Offline"}</strong><p>{online?"Queued items will retry automatically.":"New rounds remain safely stored on this device until the connection returns."}</p></div><b>{items.length} queued</b></section><section className="sync-list"><div className="sync-list-head"><span>Item</span><span>Status</span><span>Attempts</span><span>Next action</span></div>{items.map(item=><article key={item.id}><div><strong>{item.kind==="round"?item.payload.courseName||"Golf round":"Queued item"}</strong><span>{when(item.created_at)} · {item.payload.entryMode||"quick"}</span><small>{item.id}</small></div><b className={item.status}>{item.status}</b><span>{item.attempts}</span><div className="sync-actions"><button disabled={!online||working} onClick={()=>retry(item.id)}>Retry</button><button onClick={()=>discard(item.id)}>Discard</button></div>{item.last_error&&<p>{item.last_error}{item.next_attempt_at?` · automatic retry after ${when(item.next_attempt_at)}`:""}</p>}</article>)}{!items.length&&<div className="empty-state compact"><h2>Everything is synced</h2><p>There is no locally queued work waiting to reach the database.</p></div>}</section><div className="sync-explainer"><strong>How this works</strong><p>Rounds are written to durable device storage first. Synchronisation is atomic and duplicate-safe: the round, performance bands and detailed shots arrive together, and a retry cannot create a second copy.</p></div></AppShell>}
